import{_ as a,C as s,o as d,c as m,j as i,a as l,E as t,a3 as r}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"千字文 · 全篇","description":"《千字文》全篇一千字，按内容分八节，逐节给原文、引读与字词。","frontmatter":{"title":"千字文 · 全篇","description":"《千字文》全篇一千字，按内容分八节，逐节给原文、引读与字词。","category":"guide","aliases":["千字文","千字文全篇"],"source":["《千字文》（通行本）"]},"headers":[],"relativePath":"lizhimingde/qianziwen/chapter-01.md","filePath":"lizhimingde/qianziwen/chapter-01.md","lastUpdated":1789470132000}'),u={name:"lizhimingde/qianziwen/chapter-01.md"};function p(y,n,h,b,_,j){const o=s("DaoReadingPrelude"),g=s("DaoTextReading"),e=s("DaoKeywordCards");return d(),m("div",null,[n[0]||(n[0]=i("h1",{id:"千字文-·-全篇",tabindex:"-1"},[l("千字文 · 全篇 "),i("a",{class:"header-anchor",href:"#千字文-·-全篇","aria-label":'Permalink to "千字文 · 全篇"'},"​")],-1)),t(o,{title:"一千字里的中国：先通读，再八节细看",summary:"《千字文》四字一句、两句一韵，一千字不重不漏，本是为识字而编，却由识字铺开成一篇缩写的中国文化小百科：从天地开辟讲到日用起居，中间插入上古史、修身、人伦、都邑、史地与农政。这一页把全文按内容分为八节，每节都有原文、一句引读与该节字词。",points:[{label:"先读",text:"先顺着八节把原文通读一遍，遇到不认得的字不必停下。"},{label:"再辨",text:"留意它的走法：由天及地、由外及内、由史及身，一层层收到日用。"},{label:"后想",text:"读完之后再看：这一千字里，哪几句和你现在的日子有关。"}],hint:"竹简 / 经典两种读法可随时切换（切换后全页同步）；经典模式下点带底色的词可看释义。"}),n[1]||(n[1]=i("h2",{id:"jie-1",tabindex:"-1"},[l("一、天地自然 "),i("a",{class:"header-anchor",href:"#jie-1","aria-label":'Permalink to "一、天地自然 {#jie-1}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第一节原文：天地自然",paragraphs:["天地玄黄，宇宙洪荒。","日月盈昃，辰宿列张。","寒来暑往，秋收冬藏。","闰余成岁，律吕调阳。","云腾致雨，露结为霜。","金生丽水，玉出昆冈。","剑号巨阙，珠称夜光。","果珍李柰，菜重芥姜。","海咸河淡，鳞潜羽翔。"],"classic-groups":[{id:"tian",start:0,end:5,label:"天地日月"},{id:"wu",start:5,end:9,label:"金玉物产"}],glossary:[{id:"ze",term:"昃",pinyin:"zè",meaning:"日西斜。日月盈昃，说的是月由圆到缺、日由中天到西斜，都是运行。"},{id:"runyu",term:"闰余",pinyin:"rùn yú",meaning:"历法术语。一年实际日数比整数日多出零头，累积而成闰月；闰月与岁余相配，才成岁时。"},{id:"lvlv",term:"律吕",pinyin:"lǜ lǚ",meaning:"古乐十二音：六律为阳、六吕为阴。古人以十二律与十二月相应，用律管候气来调正节气。"},{id:"juque",term:"巨阙",pinyin:"jù què",meaning:"春秋时越王勾践所铸宝剑之名，与湛卢、纯钩等并称。"},{id:"yeguang",term:"夜光",pinyin:"yè guāng",meaning:"夜明珠。一说即隋侯之珠，夜里能发光。"},{id:"nai",term:"柰",pinyin:"nài",meaning:"柰树之果，形似苹果而小。果珍李柰，指果中珍品是李与柰。"}]}),n[2]||(n[2]=r("<blockquote><p><strong>引读</strong>：前五句讲天——颜色、日月、寒暑、闰律、云霜；后四句落地——金玉剑珠、果蔬、海河鱼鸟。先看清这层天／地之分，再看它其实是按「由远及近、由大到小」排下来的。</p></blockquote><p><strong>逐句释义</strong></p><ul><li><strong>天地玄黄，宇宙洪荒。</strong> 天色深玄，地色黄厚；宇宙初开，洪蒙荒远。 <ul><li>玄=深黑色（天之色）；黄=土地之色</li><li>&quot;宇&quot;指空间，&quot;宙&quot;指时间</li></ul></li><li><strong>日月盈昃，辰宿列张。</strong> 日满则亏（盈），日西斜（昃）；星辰罗列，布张天际。 <ul><li>昃（zè）：太阳偏西</li><li>辰宿：星辰宿曜</li></ul></li><li><strong>寒来暑往，秋收冬藏。</strong> 四季更替，寒暑循环；秋天收获，冬天储藏。 <ul><li>自然规律之总结</li></ul></li><li><strong>闰余成岁，律吕调阳。</strong> 积累闰月以成完整年份；六律六吕，调和阴阳之气。 <ul><li>闰余：历法中余出的天数积为闰月</li><li>律吕：古代音律，律为阳，吕为阴，共十二律</li></ul></li><li><strong>云腾致雨，露结为霜。</strong> 云气上腾化为雨；露水凝结成为霜。 <ul><li>水循环与节气变化</li></ul></li><li><strong>金生丽水，玉出昆冈。</strong> 黄金产于丽水；美玉出自昆仑。 <ul><li>丽水：古地名，产金之地；昆冈：昆仑山脉</li></ul></li><li><strong>剑号巨阙，珠称夜光。</strong> 宝剑以巨阙为名贵；明珠以夜光为珍称。 <ul><li>巨阙：古代名剑，传为欧冶子所铸</li><li>夜光：夜明珠</li></ul></li><li><strong>果珍李柰，菜重芥姜。</strong> 果品中李子和柰最珍贵；蔬菜中芥菜和生姜最受重视。 <ul><li>柰（nài）：古代苹果</li></ul></li><li><strong>海咸河淡，鳞潜羽翔。</strong> 海水咸，河水淡；鱼类潜游水中，鸟类振翅飞翔。 <ul><li>概括动物世界与自然现象</li></ul></li></ul>",3)),t(e,{items:[{term:"玄黄",pinyin:["xuán","huáng"],meaning:"天玄而地黄。语本《易·坤·文言》「夫玄黄者，天地之杂也，天玄而地黄」，指天地初成时的颜色。"},{term:"洪荒",pinyin:["hóng","huāng"],meaning:"广大荒远、浑沌未分的样子。宇指上下四方，宙指古往今来，「宇宙」合起来就是时间与空间。"},{term:"盈昃",pinyin:["yíng","zè"],meaning:"月圆为盈、日斜为昃。《易·丰》「日中则昃，月盈则食」讲的是同一个道理：到极处就要转。"},{term:"闰余成岁",pinyin:["rùn","yú","chéng","suì"],meaning:"置闰以成年。阴历一年约三百五十四日，与太阳年差约十一日，三年一闰、五年再闰，才不至于寒暑错位。"},{term:"律吕调阳",pinyin:["lǜ","lǚ","tiáo","yáng"],meaning:"以十二律对应十二月来调正节气。律为阳声、吕为阴声，古人候气于律管，观其应时而动。"},{term:"丽水",pinyin:["lì","shuǐ"],meaning:"古称金沙江为丽水，一说其地出金。「金生丽水」即金沙出于丽水。"},{term:"昆冈",pinyin:["kūn","gāng"],meaning:"昆仑山，古以为产玉之地。《尚书·胤征》有「火炎昆冈，玉石俱焚」之语。"},{term:"李柰芥姜",pinyin:["lǐ","nài","jiè","jiāng"],meaning:"李、柰是果中珍品，芥、姜是菜中要味。「菜重芥姜」的「重」是看重，不是分量重。"},{term:"鳞潜羽翔",pinyin:["lín","qián","yǔ","xiáng"],meaning:"鱼在水中潜、鸟在空中翔——由海河写到水陆众生，收束这一节的自然之景。"}]}),n[3]||(n[3]=i("h2",{id:"jie-2",tabindex:"-1"},[l("二、上古治世 "),i("a",{class:"header-anchor",href:"#jie-2","aria-label":'Permalink to "二、上古治世 {#jie-2}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第二节原文：上古治世",paragraphs:["龙师火帝，鸟官人皇。","始制文字，乃服衣裳。","推位让国，有虞陶唐。","吊民伐罪，周发殷汤。","坐朝问道，垂拱平章。","爱育黎首，臣伏戎羌。","遐迩一体，率宾归王。","鸣凤在竹，白驹食场。","化被草木，赖及万方。"],"classic-groups":[{id:"guan",start:0,end:2,label:"官制与文字"},{id:"rang",start:2,end:4,label:"禅让与征伐"},{id:"de",start:4,end:9,label:"治世与德化"}],glossary:[{id:"longshi",term:"龙师",pinyin:"lóng shī",meaning:"传说伏羲氏以龙名官，故称龙师，是上古以图腾纪官的标志。"},{id:"niaoguan",term:"鸟官",pinyin:"niǎo guān",meaning:"传说少昊氏以鸟名官，故称鸟官，与「龙师」对举。"},{id:"chuigong",term:"垂拱",pinyin:"chuí gǒng",meaning:"垂衣拱手。形容君主不必亲自操劳，天下自安。"},{id:"pingzhang",term:"平章",pinyin:"píng zhāng",meaning:"辨别彰明。语本《尚书·尧典》「平章百姓」，指辨明政事得失。"},{id:"lishou",term:"黎首",pinyin:"lí shǒu",meaning:"黎民百姓。黎是众多，首指人民。"},{id:"rongqiang",term:"戎羌",pinyin:"róng qiāng",meaning:"西戎与羌，泛指西部边地的部族。"},{id:"xiaer",term:"遐迩",pinyin:"xiá ěr",meaning:"远近。遐迩一体，指远近之地合为一体。"}]}),n[4]||(n[4]=r("<blockquote><p><strong>引读</strong>：这一节是压缩过的上古史：先立官制与文字衣裳，再讲禅让与征伐，末尾落在「德化所及」。留意「吊民伐罪」与「垂拱平章」并置——除暴与无为，是古人心中治世的两只手。</p></blockquote><p><strong>逐句释义</strong></p><ul><li><strong>龙师火帝，鸟官人皇。</strong> 伏羲以龙纪官，神农为火帝，少昊以鸟名官，人皇为三皇之一。 <ul><li>上古帝王之称</li></ul></li><li><strong>始制文字，乃服衣裳。</strong> 仓颉始造文字；嫘（léi）祖始制衣裳。 <ul><li>文明起源的两大标志</li></ul></li><li><strong>推位让国，有虞陶唐。</strong> 禅让帝位，有虞氏（舜）与陶唐氏（尧）互相推让。 <ul><li>儒家推崇的上古禅让制度</li></ul></li><li><strong>吊民伐罪，周发殷汤。</strong> 抚慰百姓、讨伐暴君：周武王（发）伐纣，商汤伐桀。 <ul><li>发：周武王姬发；汤：商汤</li></ul></li><li><strong>坐朝问道，垂拱平章。</strong> 端坐朝堂，询问治国之道；垂衣拱手，天下太平。 <ul><li>垂拱：无为而治的理想政治</li></ul></li><li><strong>爱育黎首，臣伏戎羌。</strong> 仁慈的君王爱护和抚育黎民百姓，使得国家的德行广施、威望远播，连边境的戎、羌等少数民族也真心归顺、臣服。 <ul><li>黎首：黎民百姓（黑发之人）</li></ul></li><li><strong>遐迩一体，率宾归王。</strong> 远近融为一体；万方宾服，归顺王化。</li><li><strong>鸣凤在竹，白驹食场。</strong> 凤凰鸣于竹林（太平祥瑞）；白驹悠游食于场圃（贤才得用）。 <ul><li>均为太平盛世之象征</li></ul></li><li><strong>化被草木，赖及万方。</strong> 王者教化遍及草木；恩泽惠及天下万方。</li></ul>",3)),t(e,{items:[{term:"龙师火帝",pinyin:["lóng","shī","huǒ","dì"],meaning:"伏羲氏以龙纪官，神农氏以火纪官。指上古以图腾、以火政命名官制的传说时代。"},{term:"鸟官人皇",pinyin:["niǎo","guān","rén","huáng"],meaning:"少昊氏以鸟名官，人皇氏为传说中三皇之一。连上句，泛指三皇五帝之世。"},{term:"始制文字",pinyin:["shǐ","zhì","wén","zì"],meaning:"传说黄帝之史仓颉造字。有了文字，政令与经验才可传之久远。"},{term:"乃服衣裳",pinyin:["nǎi","fú","yī","shang"],meaning:"传说黄帝制衣裳、嫘祖养蚕。自此有了服制，人别于禽兽。"},{term:"推位让国",pinyin:["tuī","wèi","ràng","guó"],meaning:"禅让：尧让位于舜、舜让位于禹，不传子而传贤。"},{term:"有虞陶唐",pinyin:["yǒu","yú","táo","táng"],meaning:"有虞氏指舜，陶唐氏指尧。以氏号代称两位古帝。"},{term:"吊民伐罪",pinyin:["diào","mín","fá","zuì"],meaning:"抚慰百姓、讨伐暴君。周发指周武王姬发，殷汤指商汤，指汤伐桀、武伐纣。"},{term:"垂拱平章",pinyin:["chuí","gǒng","píng","zhāng"],meaning:"垂衣拱手而天下治，同时辨明政事得失。无为不是不问事，是先把人和制度立好。"},{term:"鸣凤在竹",pinyin:["míng","fèng","zài","zhú"],meaning:"凤凰鸣于竹间、白马食于场圃，古人以为德政所致之祥瑞。二句是「化被草木」的图景。"}]}),n[5]||(n[5]=i("h2",{id:"jie-3",tabindex:"-1"},[l("三、修身之本 "),i("a",{class:"header-anchor",href:"#jie-3","aria-label":'Permalink to "三、修身之本 {#jie-3}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第三节原文：修身之本",paragraphs:["盖此身发，四大五常。","恭惟鞠养，岂敢毁伤。","女慕贞洁，男效才良。","知过必改，得能莫忘。","罔谈彼短，靡恃己长。","信使可覆，器欲难量。","墨悲丝染，诗赞羔羊。","景行维贤，克念作圣。","德建名立，形端表正。","空谷传声，虚堂习听。","祸因恶积，福缘善庆。","尺璧非宝，寸阴是竞。"],"classic-groups":[{id:"shen",start:0,end:2,label:"身体发肤"},{id:"yan",start:2,end:6,label:"言行与改过"},{id:"de",start:6,end:9,label:"德行与教化"},{id:"xi",start:9,end:12,label:"因果与惜时"}],glossary:[{id:"sida",term:"四大",pinyin:"sì dà",meaning:"古印度用以说明身体的四种元素：地、水、火、风。此处与「五常」（仁义礼智信）并举——一说身、一说德。"},{id:"juyang",term:"鞠养",pinyin:"jū yǎng",meaning:"养育。恭惟鞠养，是恭敬地念及父母养育之劳。"},{id:"wang",term:"罔",pinyin:"wǎng",meaning:"不要。罔谈彼短，即不要议论别人的短处。"},{id:"mi",term:"靡",pinyin:"mǐ",meaning:"不要。靡恃己长，即不要倚仗自己的长处。"},{id:"fu",term:"覆",pinyin:"fù",meaning:"核对、验察。信使可覆，指说出口的话要经得起反复核对。"},{id:"jingxing",term:"景行",pinyin:"jǐng xíng",meaning:"大道、光明的德行。语本《诗经·小雅》「高山仰止，景行行止」。"},{id:"chibi",term:"尺璧",pinyin:"chǐ bì",meaning:"直径一尺的美玉，喻贵重之物。尺璧非宝、寸阴是竞——美玉不算宝，光阴才要争。"}]}),n[6]||(n[6]=r("<blockquote><p><strong>引读</strong>：从「身体发肤」起，经改过、言行、德行，收到惜时。三组对举值得停一停：知过必改／得能莫忘，罔谈彼短／靡恃己长，信使可覆／器欲难量——讲的都是「向内收」。</p></blockquote><p><strong>逐句释义</strong></p><ul><li><strong>盖此身发，四大五常。</strong> 四大为地水火风，五常为仁义礼智信。一句里把「身」与「德」两样根基一起立住。</li><li><strong>恭惟鞠养，岂敢毁伤。</strong> 恭敬思念父母养育之恩，岂敢毁伤身体。 <ul><li>呼应《孝经》：&quot;身体发肤，受之父母，不敢毁伤。&quot;</li></ul></li><li><strong>女慕贞洁，男效才良。</strong> 女子仰慕贞洁之德；男子效法才德兼备之人。</li><li><strong>知过必改，得能莫忘。</strong> 知道过错必须改正；学到本领不要忘记。</li><li><strong>罔谈彼短，靡恃己长。</strong> 不要谈论他人的短处；不要依仗自己的长处。 <ul><li>罔：不要；靡：不要</li></ul></li><li><strong>信使可覆，器欲难量。</strong> 诚信之言可以验证；器量要宽宏难以测量。</li><li><strong>墨悲丝染，诗赞羔羊。</strong> 墨子悲叹白丝被染（近朱者赤之意）；《诗经》赞美羔羊（比喻正直之臣）。 <ul><li>典故：《墨子·所染》</li></ul></li><li><strong>景行维贤，克念作圣。</strong> 仰慕高尚品行才能成为贤人；能够克制私念便可成为圣人。 <ul><li>景行：高尚的品行</li></ul></li><li><strong>德建名立，形端表正。</strong> 品德树立则名声自立；仪形端正则仪表自正。</li><li><strong>空谷传声，虚堂习听。</strong> 空谷中声音传得很远；空旷的厅堂中回声清晰。 <ul><li>比喻德行影响深远</li></ul></li><li><strong>祸因恶积，福缘善庆。</strong> 祸患因积累恶行而来；福分因积累善行而至。 <ul><li>善恶因果之论</li></ul></li><li><strong>尺璧非宝，寸阴是竞。</strong> 一尺大的璧玉不算珍宝；一寸光阴才值得珍惜争取。 <ul><li>时间之珍贵</li></ul></li></ul>",3)),t(e,{items:[{term:"盖此身发",pinyin:["gài","cǐ","shēn","fà"],meaning:"语本《孝经》「身体发肤，受之父母，不敢毁伤，孝之始也」。盖是发语词，这一节由此起。"},{term:"四大五常",pinyin:["sì","dà","wǔ","cháng"],meaning:"四大为地水火风，五常为仁义礼智信。一句里把「身」与「德」两样根基一起立住。"},{term:"恭惟鞠养",pinyin:["gōng","wéi","jū","yǎng"],meaning:"恭敬地想父母抚育之劳；由此才有「岂敢毁伤」——不敢轻慢这具受之父母的身体。"},{term:"墨悲丝染",pinyin:["mò","bēi","sī","rǎn"],meaning:"《墨子·所染》载墨子见染丝而悲：丝入青则青、入黄则黄，一染便难复白。喻人所处所习，熏染最要紧。"},{term:"诗赞羔羊",pinyin:["shī","zàn","gāo","yáng"],meaning:"《诗经·召南·羔羊》以「羔羊之皮，素丝五紽」称美在位者节俭正直。"},{term:"景行维贤",pinyin:["jǐng","xíng","wéi","xián"],meaning:"效法大道上的贤者。「维」是维系、依循。"},{term:"克念作圣",pinyin:["kè","niàn","zuò","shèng"],meaning:"能克制杂念、念念守正，就可以作圣人。语本《尚书·多方》「惟圣罔念作狂，惟狂克念作圣」。"},{term:"空谷传声",pinyin:["kōng","gǔ","chuán","shēng"],meaning:"空谷里喊一声，回响清楚；虚堂之中，声音易听。喻心空则能受、能察。"},{term:"尺璧寸阴",pinyin:["chǐ","bì","cùn","yīn"],meaning:"语本《淮南子》「圣人不贵尺之璧而重寸之阴」。一尺美玉不算宝，一寸光阴才值得去争。"}]}),n[7]||(n[7]=i("h2",{id:"jie-4",tabindex:"-1"},[l("四、人伦持守 "),i("a",{class:"header-anchor",href:"#jie-4","aria-label":'Permalink to "四、人伦持守 {#jie-4}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第四节原文：人伦持守",paragraphs:["资父事君，曰严与敬。","孝当竭力，忠则尽命。","临深履薄，夙兴温凊。","似兰斯馨，如松之盛。","川流不息，渊澄取映。","容止若思，言辞安定。","笃初诚美，慎终宜令。","荣业所基，籍甚无竟。","学优登仕，摄职从政。","存以甘棠，去而益咏。","乐殊贵贱，礼别尊卑。","上和下睦，夫唱妇随。","外受傅训，入奉母仪。","诸姑伯叔，犹子比儿。","孔怀兄弟，同气连枝。","交友投分，切磨箴规。","仁慈隐恻，造次弗离。","节义廉退，颠沛匪亏。","性静情逸，心动神疲。","守真志满，逐物意移。","坚持雅操，好爵自縻。"],"classic-groups":[{id:"qin",start:0,end:5,label:"事亲事君"},{id:"yi",start:5,end:9,label:"仪态与立身"},{id:"shi",start:9,end:12,label:"出仕与礼序"},{id:"jia",start:12,end:16,label:"家世人伦"},{id:"jiao",start:16,end:21,label:"交友与性情"}],glossary:[{id:"wenqing",term:"温凊",pinyin:"wēn qìng",meaning:"让父母冬暖夏凉。凊读 qìng，是凉爽。语本《礼记·曲礼》「冬温而夏凊，昏定而晨省」。"},{id:"yuancheng",term:"渊澄",pinyin:"yuān chéng",meaning:"深潭澄清。渊澄取映，指水静而清，可以照见物影——喻心清可鉴。"},{id:"jishen",term:"籍甚",pinyin:"jí shèn",meaning:"声名盛大、籍籍有名。籍甚无竟，指声誉传之不尽。"},{id:"gantang",term:"甘棠",pinyin:"gān táng",meaning:"周召伯巡行听政，曾在甘棠树下，后人思其德而爱其树，作《召南·甘棠》。存以甘棠、去而益咏，指在位有惠政，离去后更被怀念。"},{id:"fuxun",term:"傅训",pinyin:"fù xùn",meaning:"师傅的训导。外受傅训、入奉母仪——在外受师训，在家奉母教。"},{id:"youzi",term:"犹子",pinyin:"yóu zǐ",meaning:"侄子。诸姑伯叔、犹子比儿，是说对姑叔而言，侄子就如自己的孩子。"},{id:"konghuai",term:"孔怀",pinyin:"kǒng huái",meaning:"格外怀念。语本《诗经·小雅·常棣》「兄弟孔怀」，后以「孔怀」代指兄弟。"},{id:"qiemo",term:"切磨箴规",pinyin:"qiē mó zhēn guī",meaning:"切磋琢磨、规劝告诫——朋友之间相互砥砺。「切磨」出自《诗经》「如切如磋，如琢如磨」。"}]}),n[8]||(n[8]=r("<blockquote><p><strong>引读</strong>：这是全书最长的一节，可分五层顺读：做人的本分（孝忠、谨敬）→ 做事的仪态（容止、慎终）→ 出仕的次第（学优登仕、甘棠遗爱）→ 家中人伦（傅训母仪、姑叔兄弟、交友）→ 心性（性静情逸、守真志满）。末尾「好爵自縻」是落点：里面守得住，外面的名位反而自来。</p></blockquote><p><strong>逐句释义</strong></p><ul><li><strong>资父事君，曰严与敬。</strong> 侍奉父亲、服事君主，要严肃而恭敬。</li><li><strong>孝当竭力，忠则尽命。</strong> 尽孝要竭尽全力；尽忠要不惜生命。</li><li><strong>临深履薄，夙兴温凊。</strong> 如临深渊、如履薄冰（谨慎行事）；早起晚睡，冬温夏凊（侍奉父母）。 <ul><li>温凊（qìng）：冬天温被，夏天扇凉，出自《礼记》</li></ul></li><li><strong>似兰斯馨，如松之盛。</strong> 品德如兰花般芬芳；节操如松树般茂盛。</li><li><strong>川流不息，渊澄取映。</strong> 如河川流水不息；如深渊澄澈可照映。 <ul><li>比喻君子品德之持续与清明</li></ul></li><li><strong>容止若思，言辞安定。</strong> 仪容举止沉静若有所思；言语辞令安详稳定。</li><li><strong>笃初诚美，慎终宜令。</strong> 做事开始时认真诚恳固然好；谨慎善终才更为重要。 <ul><li>有始有终之道</li></ul></li><li><strong>荣业所基，籍甚无竟。</strong> 荣耀事业的根基在此；美名传扬，无有穷尽。</li><li><strong>学优登仕，摄职从政。</strong> 学业优秀则出仕为官；担任职务，参与政事。 <ul><li>出自《论语》：&quot;学而优则仕。&quot;</li></ul></li><li><strong>存以甘棠，去而益咏。</strong> 在任时如甘棠树荫庇百姓；离任后百姓更加颂扬。 <ul><li>典故：《诗经·甘棠》召伯曾在甘棠树下听讼，后人爱树思人</li></ul></li><li><strong>乐殊贵贱，礼别尊卑。</strong> 音乐区分贵贱之别；礼仪分别尊卑之序。</li><li><strong>上和下睦，夫唱妇随。</strong> 上下和睦相处；夫唱妇和相随。</li><li><strong>外受傅训，入奉母仪。</strong> 在外接受师傅的教诲；在家奉行母亲的仪范。</li><li><strong>诸姑伯叔，犹子比儿。</strong> 对待姑母、伯父、叔父，如同对待自己的子女一般。</li><li><strong>孔怀兄弟，同气连枝。</strong> 兄弟之间最为亲爱；同气相连，如树之枝干。 <ul><li>孔怀：非常思念，出自《诗经》</li></ul></li><li><strong>交友投分，切磨箴规。</strong> 交友要志趣相投；互相切磋学问，规劝过失。 <ul><li>箴：本义是古代的竹针，有劝告、劝戒之意。</li></ul></li><li><strong>仁慈隐恻，造次弗离。</strong> 仁慈恻隐之心，仓促之间也不离弃。 <ul><li>造次：仓促、紧急之时</li></ul></li><li><strong>节义廉退，颠沛匪亏。</strong> 节操、义气、廉洁、谦退，即使颠沛流离也不亏损。</li><li><strong>性静情逸，心动神疲。</strong> 本性宁静则情志安逸；心绪躁动则精神疲惫。</li><li><strong>守真志满，逐物意移。</strong> 守住本真则志向充实；追逐外物则心意游移。</li><li><strong>坚持雅操，好爵自縻。</strong> 坚持高雅的节操；美好的爵位自然会来系住你。 <ul><li>縻（mí）：系缚、留住</li></ul></li></ul>",3)),t(e,{items:[{term:"资父事君",pinyin:["zī","fù","shì","jūn"],meaning:"以事父之道事君。语本《孝经》「资于事父以事君，而敬同」。严与敬，是这一节的总纲。"},{term:"临深履薄",pinyin:["lín","shēn","lǚ","bó"],meaning:"如临深渊、如履薄冰。语出《诗经·小雅·小旻》，形容存心戒慎。"},{term:"夙兴温凊",pinyin:["sù","xīng","wēn","qìng"],meaning:"早起操持，冬使父母温、夏使父母凉。是「孝当竭力」落到日常的样子。"},{term:"川流不息",pinyin:["chuān","liú","bù","xī"],meaning:"如河水奔流不止，如深潭澄澈可照——一喻德泽绵长，一喻心境清明。"},{term:"笃初慎终",pinyin:["dǔ","chū","shèn","zhōng"],meaning:"开头诚恳固然好，能慎重收尾更难。《诗经》「靡不有初，鲜克有终」说的是同一件事。"},{term:"学优登仕",pinyin:["xué","yōu","dēng","shì"],meaning:"学有余力便出仕任事。语本《论语》「学而优则仕」；摄职从政，是代理职事、参与政务。"},{term:"甘棠遗爱",pinyin:["gān","táng","yí","ài"],meaning:"召伯听政于甘棠树下，去后民思其人而爱其树。后世以「甘棠遗爱」称颂离任后仍被怀念的惠政。"},{term:"孔怀同气",pinyin:["kǒng","huái","tóng","qì"],meaning:"兄弟最为相念，同气连枝如一棵树上的枝干，血脉同源。"},{term:"好爵自縻",pinyin:["hǎo","jué","zì","mí"],meaning:"美好的爵位会自己系到身上。「縻」是系、拴。内守雅操，外来的名位反而不必去求。"}]}),n[9]||(n[9]=i("h2",{id:"jie-5",tabindex:"-1"},[l("五、都邑典籍 "),i("a",{class:"header-anchor",href:"#jie-5","aria-label":'Permalink to "五、都邑典籍 {#jie-5}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第五节原文：都邑典籍",paragraphs:["都邑华夏，东西二京。","背邙面洛，浮渭据泾。","宫殿盘郁，楼观飞惊。","图写禽兽，画彩仙灵。","丙舍旁启，甲帐对楹。","肆筵设席，鼓瑟吹笙。","升阶纳陛，弁转疑星。","右通广内，左达承明。","既集坟典，亦聚群英。","杜稿钟隶，漆书壁经。","府罗将相，路侠槐卿。","户封八县，家给千兵。","高冠陪辇，驱毂振缨。","世禄侈富，车驾肥轻。","策功茂实，勒碑刻铭。"],"classic-groups":[{id:"jing",start:0,end:4,label:"两京形胜"},{id:"gong",start:4,end:7,label:"宫室陈设"},{id:"dian",start:7,end:10,label:"典籍与贤才"},{id:"jiang",start:10,end:15,label:"将相世禄"}],glossary:[{id:"erjing",term:"二京",pinyin:"èr jīng",meaning:"西京长安与东京洛阳。汉唐皆两京并置，故称东西二京。"},{id:"mang",term:"邙",pinyin:"máng",meaning:"北邙山，在洛阳之北。背邙面洛，写洛阳背山面水的地势；浮渭据泾，写长安倚渭水、据泾水。"},{id:"jiazhang",term:"甲帐",pinyin:"jiǎ zhàng",meaning:"华美的帐幕。丙舍是宫中别室，甲帐对楹写宫室内外陈设之盛。"},{id:"bian",term:"弁",pinyin:"biàn",meaning:"古代男子加冠时所用的一种帽子。弁转疑星，写朝会时冠饰转动如星。"},{id:"guangnei",term:"广内",pinyin:"guǎng nèi",meaning:"汉宫广内殿，为收藏秘书之所；承明殿则是贤士待诏之处。一藏典籍、一聚贤才。"},{id:"fendian",term:"坟典",pinyin:"fén diǎn",meaning:"三坟、五典，传说中上古典籍之名，后泛指古书。"},{id:"dugao",term:"杜稿钟隶",pinyin:"dù gǎo zhōng lì",meaning:"杜度的章草稿书、钟繇的隶书，都是书法名迹；漆书是先人以漆书写的古书，壁经指自孔子旧宅壁中所得之经。"},{id:"huaiqing",term:"槐卿",pinyin:"huái qīng",meaning:"周代朝廷植三槐，三公位其下，故以槐卿称三公九卿。路侠槐卿，写重臣夹道而立。"}]}),n[10]||(n[10]=r("<blockquote><p><strong>引读</strong>：先立两京形势，再写宫殿朝会，然后一转——「既集坟典，亦聚群英」：都城的厚重不在宫室，而在典籍与人才。读时留意它「由景入人、由人入文」的次序，末尾又回到功臣世禄与刻石记功。</p></blockquote><p><strong>逐句释义</strong></p><ul><li><strong>都邑华夏，东西二京。</strong> 华夏的都城，有东西两京。 <ul><li>东京：洛阳；西京：长安</li></ul></li><li><strong>背邙面洛，浮渭据泾。</strong> 洛阳背靠邙山，面向洛水；长安浮临渭水，据守泾河。</li><li><strong>宫殿盘郁，楼观飞惊。</strong> 宫殿盘旋郁立；楼阁高耸，令人惊叹如欲飞去。</li><li><strong>图写禽兽，画彩仙灵。</strong> 绘画飞禽走兽；彩绘神仙灵异。</li><li><strong>丙舍旁启，甲帐对楹。</strong> 丙舍（宫中别室）旁门开启；华美的帷帐对着廊柱。</li><li><strong>肆筵设席，鼓瑟吹笙。</strong> 大摆筵席；鼓瑟吹笙，奏乐欢宴。</li><li><strong>升阶纳陛，弁转疑星。</strong> 登上台阶进入殿陛；冠上珠饰转动，疑是繁星。 <ul><li>弁（biàn）：古代礼帽</li></ul></li><li><strong>右通广内，左达承明。</strong> 右边通向广内殿（藏书之所）；左边通达承明殿（待诏之所）。</li><li><strong>既集坟典，亦聚群英。</strong> 既收藏了三坟五典等古籍；又汇聚了天下英才。</li><li><strong>杜稿钟隶，漆书壁经。</strong> 杜度草书、钟繇（yáo）隶书；漆书古文、壁中经典。 <ul><li>均为珍贵书法与典籍</li></ul></li><li><strong>府罗将相，路侠槐卿。</strong> 府中罗列将帅宰相；道路两旁槐树下站立三公九卿。 <ul><li>槐卿：三公（槐）九卿之称</li></ul></li><li><strong>户封八县，家给千兵。</strong> 封赐八县之户；赐给千名兵卒护卫。</li><li><strong>高冠陪辇，驱毂振缨。</strong> 头戴高冠陪同天子车驾；驱车前行，缨带飘动。</li><li><strong>世禄侈富，车驾肥轻。</strong> 世代享受俸禄，奢侈富贵；车马肥壮，轻裘暖服。</li><li><strong>策功茂实，勒碑刻铭。</strong> 记录功勋卓著的事迹；勒石立碑，刻铭传世。</li></ul>",3)),t(e,{items:[{term:"东西二京",pinyin:["dōng","xī","èr","jīng"],meaning:"洛阳为东京、长安为西京。华夏是中国的旧称——这一句把「都城」放到天下的尺度上说。"},{term:"背邙面洛",pinyin:["bèi","máng","miàn","luò"],meaning:"洛阳背靠北邙山、面朝洛水；长安则渭水环绕、泾水为据。两句写形胜，也写择都之理。"},{term:"宫殿盘郁",pinyin:["gōng","diàn","pán","yù"],meaning:"宫殿曲折深远、层层叠叠，楼观高峻欲飞，望之令人惊。"},{term:"丙舍甲帐",pinyin:["bǐng","shè","jiǎ","zhàng"],meaning:"别室在旁开启，华帐对着厅柱。写宫室的陈设排布。"},{term:"弁转疑星",pinyin:["biàn","zhuǎn","yí","xīng"],meaning:"登阶入殿时冠饰转动，望去像一片星。写朝会仪容之盛。"},{term:"广内承明",pinyin:["guǎng","nèi","chéng","míng"],meaning:"广内殿藏书，承明殿待士。右通、左达两语，把宫室与文事连在一起。"},{term:"杜稿钟隶",pinyin:["dù","gǎo","zhōng","lì"],meaning:"杜度的章草、钟繇的隶书，与漆书、壁经并举——写典籍与书法之富。"},{term:"路侠槐卿",pinyin:["lù","xiá","huái","qīng"],meaning:"府中罗列将相，路上夹道而立的是三公九卿。「侠」通「夹」。"},{term:"勒碑刻铭",pinyin:["lè","bēi","kè","míng"],meaning:"把功劳刻在碑石与铭器上。策功茂实、勒碑刻铭，是这一节写功业的落点。"}]}),n[11]||(n[11]=i("h2",{id:"jie-6",tabindex:"-1"},[l("六、史地农政 "),i("a",{class:"header-anchor",href:"#jie-6","aria-label":'Permalink to "六、史地农政 {#jie-6}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第六节原文：史地农政",paragraphs:["磻溪伊尹，佐时阿衡。","奄宅曲阜，微旦孰营。","桓公匡合，济弱扶倾。","绮回汉惠，说感武丁。","俊乂密勿，多士寔宁。","晋楚更霸，赵魏困横。","假途灭虢，践土会盟。","何遵约法，韩弊烦刑。","起翦颇牧，用军最精。","宣威沙漠，驰誉丹青。","九州禹迹，百郡秦并。","岳宗泰岱，禅主云亭。","雁门紫塞，鸡田赤城。","昆池碣石，钜野洞庭。","旷远绵邈，岩岫杳冥。","治本于农，务兹稼穑。","俶载南亩，我艺黍稷。","税熟贡新，劝赏黜陟。"],"classic-groups":[{id:"xian",start:0,end:4,label:"贤相辅时"},{id:"ba",start:4,end:8,label:"士人与霸业"},{id:"jiang",start:8,end:12,label:"名将与疆域"},{id:"shan",start:12,end:15,label:"山川边塞"},{id:"nong",start:15,end:18,label:"农政为本"}],glossary:[{id:"panxi",term:"磻溪",pinyin:"pán xī",meaning:"相传姜太公垂钓之处，在今陕西宝鸡一带。此处以「磻溪」代指姜太公。"},{id:"aheng",term:"阿衡",pinyin:"ā héng",meaning:"伊尹的官号、尊称。伊尹辅商汤而兴，是贤相的代称。"},{id:"fuyue",term:"说感武丁",pinyin:"yuè gǎn wǔ dīng",meaning:"殷高宗武丁梦得贤人，求得傅说为相，殷道复兴。「说」指傅说，读 yuè。"},{id:"jiaguo",term:"假途灭虢",pinyin:"jiǎ tú miè guó",meaning:"晋献公向虞国借道伐虢，回师时顺手灭虞。后世以「假途灭虢」喻借路为名、兼并其实。"},{id:"jiasi",term:"稼穑",pinyin:"jià sè",meaning:"种曰稼、收曰穑，合指农事。治本于农、务兹稼穑，是这一节的落脚。"},{id:"taidai",term:"泰岱",pinyin:"tài dài",meaning:"泰山。五岳以泰山为宗；禅主云亭，指古帝封禅多在云云山、亭亭山。"},{id:"chuzhi",term:"黜陟",pinyin:"chù zhì",meaning:"贬降与晋升。税熟贡新之后，以劝赏黜陟考核官吏——农政与吏治相连。"}]}),n[12]||(n[12]=r("<blockquote><p><strong>引读</strong>：前半是人事，后半是地理与农政，两个字一个典故。不必纠缠每个名字，先看清两层：一讲用人得失（贤相、霸主、名将、律法），一讲守土养民（九州、五岳、边塞、稼穑）。末尾「劝赏黜陟」把土地与治人接到一起。</p></blockquote><p><strong>逐句释义</strong></p><ul><li><strong>磻溪伊尹，佐时阿衡。</strong> 姜太公钓于磻溪，伊尹出于有莘；辅佐时君，为国之栋梁。 <ul><li>磻溪：姜太公垂钓之地；阿衡：伊尹之号</li></ul></li><li><strong>奄宅曲阜，微旦孰营。</strong> 占据曲阜之地，若无周公旦，谁能经营？ <ul><li>微：若无；旦：周公姬旦</li></ul></li><li><strong>桓公匡合，济弱扶倾。</strong> 齐桓公匡正天下、会合诸侯；救济弱小，扶持倾危之国。</li><li><strong>绮回汉惠，说感武丁。</strong> 商山四皓中的绮里季使汉惠帝太子之位得保；傅说感动了殷高宗武丁。</li><li><strong>俊乂密勿，多士寔宁。</strong> 俊才贤能勤勉努力；众多贤士使国家安宁。 <ul><li>寔（shí）：确实、使……安定</li></ul></li><li><strong>晋楚更霸，赵魏困横。</strong> 晋国楚国交替称霸；赵国魏国被连横之策所困。</li><li><strong>假途灭虢，践土会盟。</strong> 晋国借道虞国灭掉虢国；晋文公在践土主持诸侯会盟。</li><li><strong>何遵约法，韩弊烦刑。</strong> 萧何遵守约法三章（简约之法）；韩非之学弊在繁苛刑法。</li><li><strong>起翦颇牧，用军最精。</strong> 白起、王翦、廉颇、李牧，用兵最为精妙。 <ul><li>战国四大名将</li></ul></li><li><strong>宣威沙漠，驰誉丹青。</strong> 威名远播沙漠之地；美誉流传于史册丹青。</li><li><strong>九州禹迹，百郡秦并。</strong> 九州大地留有大禹的足迹；百郡之地由秦始皇统一。</li><li><strong>岳宗泰岱，禅主云亭。</strong> 五岳以泰山为宗；封禅之礼以云云、亭亭二山为主。 <ul><li>泰岱：泰山</li></ul></li><li><strong>雁门紫塞，鸡田赤城。</strong> 雁门关、紫色长城（万里长城）；鸡田塞、赤城山。 <ul><li>均为著名边塞地名</li></ul></li><li><strong>昆池碣石，钜野洞庭。</strong> 昆明池、碣石山；钜野泽、洞庭湖。 <ul><li>著名山川湖泊</li></ul></li><li><strong>旷远绵邈，岩岫杳冥。</strong> 地域旷远绵延；山岩峰峦深远幽冥。</li><li><strong>治本于农，务兹稼穑。</strong> 治国之本在于农业；致力于耕种收获。 <ul><li>稼穑（jià sè）：种植与收获</li></ul></li><li><strong>俶载南亩，我艺黍稷。</strong> 开始耕作南边田亩；我种植黍米和稷谷。 <ul><li>俶（chù）：开始</li></ul></li><li><strong>税熟贡新，劝赏黜陟。</strong> 粮食成熟后缴税纳贡新粮；奖励勤劳，惩罚懒惰，升降官员。 <ul><li>黜陟（chù zhì）：降职与升职</li></ul></li></ul>",3)),t(e,{items:[{term:"磻溪伊尹",pinyin:["pán","xī","yī","yǐn"],meaning:"姜太公钓于磻溪而佐周，伊尹耕于有莘之野而佐商。两个「待时而动」的贤相。"},{term:"奄宅曲阜",pinyin:["yǎn","zhái","qū","fù"],meaning:"周公旦受封于曲阜（鲁国）；微旦孰营——若没有周公，谁来经营周室的基业。"},{term:"桓公匡合",pinyin:["huán","gōng","kuāng","hé"],meaning:"齐桓公九合诸侯、匡正天下，济弱扶倾：扶助弱小、援救倾危。"},{term:"绮回汉惠",pinyin:["qǐ","huí","hàn","huì"],meaning:"商山四皓中的绮里季出山，使刘邦打消废太子之念，保住了后来的汉惠帝。"},{term:"俊乂密勿",pinyin:["jùn","yì","mì","wù"],meaning:"俊乂指才德出众之士，密勿是勤勉用事。多士寔宁：人才众而国乃安。"},{term:"约法烦刑",pinyin:["yuē","fǎ","fán","xíng"],meaning:"萧何依刘邦「约法三章」而定汉律，律简而得人心；韩非之说主张严刑繁法，反受其弊。一句对照，讲的是法与治的分寸。"},{term:"起翦颇牧",pinyin:["qǐ","jiǎn","pō","mù"],meaning:"白起、王翦、廉颇、李牧——战国四位最善用兵的名将。"},{term:"驰誉丹青",pinyin:["chí","yù","dān","qīng"],meaning:"名声流传于图画之中。汉宣帝曾画功臣像于麒麟阁，后世以「丹青」代指功名图画。"},{term:"九州禹迹",pinyin:["jiǔ","zhōu","yǔ","jì"],meaning:"九州是禹治水后所划的天下区划，百郡是秦统一后所置之郡——疆域的两次定型。"}]}),n[13]||(n[13]=i("h2",{id:"jie-7",tabindex:"-1"},[l("七、为政隐逸 "),i("a",{class:"header-anchor",href:"#jie-7","aria-label":'Permalink to "七、为政隐逸 {#jie-7}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第七节原文：为政隐逸",paragraphs:["孟轲敦素，史鱼秉直。","庶几中庸，劳谦谨敕。","聆音察理，鉴貌辨色。","贻厥嘉猷，勉其祗植。","省躬讥诫，宠增抗极。","殆辱近耻，林皋幸即。","两疏见机，解组谁逼。","索居闲处，沉默寂寥。","求古寻论，散虑逍遥。","欣奏累遣，戚谢欢招。","渠荷的历，园莽抽条。","枇杷晚翠，梧桐早凋。","陈根委翳，落叶飘摇。","游鹍独运，凌摩绛霄。","耽读玩市，寓目囊箱。","易輶攸畏，属耳垣墙。","具膳餐饭，适口充肠。","饱饫烹宰，饥厌糟糠。","亲戚故旧，老少异粮。","妾御绩纺，侍巾帷房。","纨扇圆絜，银烛炜煌。"],"classic-groups":[{id:"cao",start:0,end:6,label:"在朝的操守"},{id:"tui",start:6,end:10,label:"见机而退"},{id:"shi",start:10,end:14,label:"草木时节"},{id:"du",start:14,end:16,label:"读书与警惕"},{id:"ri",start:16,end:21,label:"日用起居"}],glossary:[{id:"yijue",term:"贻厥嘉猷",pinyin:"yí jué jiā yóu",meaning:"留下好的谋略给后人。语本《诗经·大雅》「贻厥孙谋」；勉其祗植，是勉励后人恭敬培植。"},{id:"lingao",term:"林皋",pinyin:"lín gāo",meaning:"山林水边。殆辱近耻、林皋幸即——临近羞辱耻辱时，幸好还可以退到林泉。"},{id:"jiezhu",term:"解组",pinyin:"jiě zǔ",meaning:"解下印绶，即辞官。两疏见机、解组谁逼：汉疏广、疏受叔侄功成身退，不是被人逼走的。"},{id:"dili",term:"的历",pinyin:"dì lì",meaning:"鲜明、明净的样子。渠荷的历，写池中荷花的鲜亮。"},{id:"weiyi",term:"委翳",pinyin:"wěi yì",meaning:"枯倒而相互掩蔽。陈根委翳、落叶飘摇，写草木由盛而衰的时节。"},{id:"jiangxiao",term:"绛霄",pinyin:"jiàng xiāo",meaning:"红色的云霄。游鹍独运、凌摩绛霄，写大鸟独飞直上。"},{id:"yiyou",term:"易輶",pinyin:"yì yóu",meaning:"易是轻忽、輶是轻。易輶攸畏，指轻忽轻易之事最可畏；下句属耳垣墙，即隔墙有耳。"},{id:"zaokang",term:"糟糠",pinyin:"zāo kāng",meaning:"酒糟与米糠，指粗劣的食物。饱饫烹宰、饥厌糟糠，写饱时与饥时对食物的两种态度。"}]}),n[14]||(n[14]=r("<blockquote><p><strong>引读</strong>：这一节从「为政」转向「退居」：前六句讲在朝的操守与戒备（宠增抗极），第七句「林皋幸即」一转，后面便是退下来的日子——独处、读书、看草木荣枯。「两疏见机，解组谁逼」是这一转的关键：主动退，而不是被逼退。</p></blockquote><p><strong>逐句释义</strong></p><ul><li><strong>孟轲敦素，史鱼秉直。</strong> 孟子崇尚朴素之道；史鱼秉持正直之节。 <ul><li>史鱼：卫国大夫，以直谏著称</li></ul></li><li><strong>庶几中庸，劳谦谨敕。</strong> 力求做到中庸之道；勤劳谦逊，谨慎自律。</li><li><strong>聆音察理，鉴貌辨色。</strong> 听声音以察事理；观容貌以辨神色。</li><li><strong>贻厥嘉猷，勉其祗植。</strong> 留传美好的谋略给后人；勉励他们恭敬地树立品德。 <ul><li>猷（yóu）：谋略、道</li></ul></li><li><strong>省躬讥诫，宠增抗极。</strong> 反省自身，接受批评告诫；受到宠爱越多，越要警惕骄傲到极点。</li><li><strong>殆辱近耻，林皋幸即。</strong> 危辱将近之时，归隐山林是幸事。 <ul><li>林皋：山林高地，指隐居之所</li></ul></li><li><strong>两疏见机，解组谁逼。</strong> 汉代疏广、疏受叔侄见机而退；解下印绶辞官，谁能逼迫？ <ul><li>两疏：西汉疏广与疏受，功成身退的典范</li></ul></li><li><strong>索居闲处，沉默寂寥。</strong> 独居闲处，沉默寂寥。</li><li><strong>求古寻论，散虑逍遥。</strong> 寻求古籍，探讨义理；散去忧虑，逍遥自在。</li><li><strong>欣奏累遣，戚谢欢招。</strong> 喜悦之事奏来，积累的烦恼得以消遣；忧愁辞去，欢乐招来。</li><li><strong>渠荷的历，园莽抽条。</strong> 水渠中荷花鲜明艳丽；园中草木抽出新条。 <ul><li>的历：鲜明貌</li></ul></li><li><strong>枇杷晚翠，梧桐早凋。</strong> 枇杷树深秋仍翠绿；梧桐树秋天早早凋落。</li><li><strong>陈根委翳，落叶飘摇。</strong> 陈旧的根茎委积腐朽；落叶在风中飘摇。</li><li><strong>游鹍独运，凌摩绛霄。</strong> 大鹍鹏独自翱翔；凌云直上，摩擦红色的高天。 <ul><li>鹍（kūn）：大鸟，即鲲鹏之类；绛霄：红色高空</li></ul></li><li><strong>耽读玩市，寓目囊箱。</strong> 沉迷读书，在市场中流连；眼目寄托于书囊书箱之中。 <ul><li>典故：王充家贫，常在书肆阅读（《后汉书》）</li></ul></li><li><strong>易輶攸畏，属耳垣墙。</strong> 轻率之事最可畏惧；隔墙有耳，言行须谨慎。 <ul><li>輶（yóu）：轻</li></ul></li><li><strong>具膳餐饭，适口充肠。</strong> 备好膳食用餐，适口充饥。</li><li><strong>饱饫烹宰，饥厌糟糠。</strong> 饱足时厌烦烹宰美食；饥饿时连糟糠也甘之如饴。</li><li><strong>亲戚故旧，老少异粮。</strong> 亲戚故旧，老少饮食各有不同。</li><li><strong>妾御绩纺，侍巾帷房。</strong> 侍妾纺织绩麻；侍奉巾栉于帷房之中。</li><li><strong>纨扇圆絜，银烛炜煌。</strong> 纨扇圆洁；银烛炜煌明亮。</li></ul>",3)),t(e,{items:[{term:"孟轲敦素",pinyin:["mèng","kē","dūn","sù"],meaning:"孟轲即孟子，敦素是笃厚朴素；史鱼是卫国大夫，以刚直著称。一动一静，是两种「直」。"},{term:"庶几中庸",pinyin:["shù","jī","zhōng","yōng"],meaning:"力求合乎中庸，勤劳谦逊、谨慎自戒。「劳谦」出《易·谦》「劳谦君子，有终吉」。"},{term:"聆音察理",pinyin:["líng","yīn","chá","lǐ"],meaning:"听声音以辨情理，看容貌以别神色——审事察人的细功夫。"},{term:"省躬讥诫",pinyin:["xǐng","gōng","jī","jiè"],meaning:"反省自身、接纳讥诫。宠增抗极：恩宠越盛，越要防备「至极则反」。"},{term:"两疏见机",pinyin:["liǎng","shū","jiàn","jī"],meaning:"汉宣帝时疏广、疏受叔侄并为太子师傅，位高而主动请退，归乡以寿终。见机，是看见那个「该退」的时机。"},{term:"散虑逍遥",pinyin:["sàn","lǜ","xiāo","yáo"],meaning:"排遣忧虑而得自在。求古寻论、散虑逍遥，写退居后的日常：读书、论古、散心。"},{term:"耽读玩市",pinyin:["dān","dú","wán","shì"],meaning:"耽溺读书、玩味于市。后汉王充家贫无书，常游洛阳书肆，读所卖之书一见即能诵——用其事。"},{term:"属耳垣墙",pinyin:["zhǔ","ěr","yuán","qiáng"],meaning:"隔墙有耳。语本《诗经·小雅》「君子无易由言，耳属于垣」——说话轻易，最该提防。"},{term:"纨扇银烛",pinyin:["wán","shàn","yín","zhú"],meaning:"绢制团扇圆而洁净，银烛光辉明亮（炜煌）。写居处器物之清雅，与上一节的宫室之盛恰成对照。"}]}),n[15]||(n[15]=i("h2",{id:"jie-8",tabindex:"-1"},[l("八、起居收束 "),i("a",{class:"header-anchor",href:"#jie-8","aria-label":'Permalink to "八、起居收束 {#jie-8}"'},"​")],-1)),t(g,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第八节原文：起居收束",paragraphs:["昼眠夕寐，蓝笋象床。","弦歌酒宴，接杯举觞。","矫手顿足，悦豫且康。","嫡后嗣续，祭祀烝尝。","稽颡再拜，悚惧恐惶。","笺牒简要，顾答审详。","骸垢想浴，执热愿凉。","驴骡犊特，骇跃超骧。","诛斩贼盗，捕获叛亡。","布射僚丸，嵇琴阮啸。","恬笔伦纸，钧巧任钓。","释纷利俗，并皆佳妙。","毛施淑姿，工颦妍笑。","年矢每催，曦晖朗曜。","璇玑悬斡，晦魄环照。","指薪修祜，永绥吉劭。","矩步引领，俯仰廊庙。","束带矜庄，徘徊瞻眺。","孤陋寡闻，愚蒙等诮。","谓语助者，焉哉乎也。"],"classic-groups":[{id:"qi",start:0,end:3,label:"起居宴乐"},{id:"ji",start:3,end:6,label:"祭祀与书牒"},{id:"chang",start:6,end:9,label:"常情与除害"},{id:"jiyi",start:9,end:12,label:"技艺之妙"},{id:"tian",start:12,end:15,label:"美人与天时"},{id:"shou",start:15,end:20,label:"祝愿与收束"}],glossary:[{id:"zhengchang",term:"烝尝",pinyin:"zhēng cháng",meaning:"冬祭曰烝、秋祭曰尝，合指四时祭祀。嫡后嗣续、祭祀烝尝，写的是血脉与礼的两重延续。"},{id:"qisang",term:"稽颡",pinyin:"qǐ sǎng",meaning:"叩头，以额触地。稽颡再拜、悚惧恐惶，写祭祖时的恭敬与敬畏。"},{id:"jiandie",term:"笺牒",pinyin:"jiān dié",meaning:"书信与文牒。笺牒简要、顾答审详——写出去的从简，答回来的要详。"},{id:"chaoxiang",term:"超骧",pinyin:"chāo xiāng",meaning:"骧是马昂首奔腾。骇跃超骧，写驴骡犊特受惊后腾跃奔驰之状。"},{id:"xuanji",term:"璇玑",pinyin:"xuán jī",meaning:"北斗七星中可转动的部分，也指浑天仪一类测天之物。璇玑悬斡、晦魄环照，写星辰运转、月魄明晦循环。"},{id:"zhixin",term:"指薪修祜",pinyin:"zhǐ xīn xiū hù",meaning:"语本《庄子·养生主》「指穷于为薪，火传也，不知其尽也」——柴有尽而火相传。修祜是修福，永绥吉劭是愿长久安宁吉祥。"},{id:"shudai",term:"束带矜庄",pinyin:"shù dài jīn zhuāng",meaning:"整束衣带、端庄自持。矩步引领、俯仰廊庙、束带矜庄、徘徊瞻眺，连写四种在朝廷进退顾盼的仪态。"}]}),n[16]||(n[16]=r("<blockquote><p><strong>引读</strong>：收尾一节：先写日用起居与祭祀，再列技艺（射、丸、琴、啸、笔、纸、巧、钓），继以美人与天时（年矢、璇玑、晦魄）过渡，最后落到「指薪修祜」的祝愿，并以四个语助词收束——「焉哉乎也」。全文到此，正好一千字。</p></blockquote><p><strong>逐句释义</strong></p><ul><li><strong>昼眠夕寐，蓝笋象床。</strong> 白天小憩，夜晚安睡；蓝色竹席，象牙床榻。</li><li><strong>弦歌酒宴，接杯举觞。</strong> 弦歌助兴，酒宴欢聚；传杯举觞，开怀畅饮。</li><li><strong>矫手顿足，悦豫且康。</strong> 舞动手足；欢悦愉快，身体康健。</li><li><strong>嫡后嗣续，祭祀烝尝。</strong> 嫡子继承后嗣；祭祀冬祭（烝）秋祭（尝）。 <ul><li>烝尝：冬祭曰烝，秋祭曰尝</li></ul></li><li><strong>稽颡再拜，悚惧恐惶。</strong> 叩头再拜；恭敬惶恐。 <ul><li>稽颡（qǐ sǎng）：叩头至地</li></ul></li><li><strong>笺牒简要，顾答审详。</strong> 书写笺牒要简明扼要；回答问题要审慎详细。</li><li><strong>骸垢想浴，执热愿凉。</strong> 身体污垢时想要沐浴；手执热物时希望凉爽。 <ul><li>比喻人之常情</li></ul></li><li><strong>驴骡犊特，骇跃超骧。</strong> 驴骡牛马，惊跳腾跃，奔驰昂扬。 <ul><li>特：公牛；骧（xiāng）：马昂首奔驰</li></ul></li><li><strong>诛斩贼盗，捕获叛亡。</strong> 诛杀斩除贼寇盗匪；捕获叛逃亡命之徒。</li><li><strong>布射僚丸，嵇琴阮啸。</strong> 吕布善射，宜僚弄丸；嵇康善琴，阮籍善啸。 <ul><li>四位技艺超群之人</li></ul></li><li><strong>恬笔伦纸，钧巧任钓。</strong> 蒙恬造笔，蔡伦造纸；马钧机巧，任公子善钓。 <ul><li>四大发明与能工巧匠</li></ul></li><li><strong>释纷利俗，并皆佳妙。</strong> 化解纷争，有利于世俗；各种技艺都精妙绝伦。</li><li><strong>毛施淑姿，工颦妍笑。</strong> 毛嫱、西施姿容美丽；蹙眉（颦）也好，欢笑也美。 <ul><li>毛施：毛嫱与西施，古代两大美女</li></ul></li><li><strong>年矢每催，曦晖朗曜。</strong> 岁月如箭，催人老去；阳光明亮照耀。 <ul><li>曦（xī）：日光</li></ul></li><li><strong>璇玑悬斡，晦魄环照。</strong> 璇玑（北斗）悬转运行；月亮由晦到明，循环照耀。</li><li><strong>指薪修祜，永绥吉劭。</strong> 以薪火相传比喻修积福祉；永远安宁，吉祥美好。 <ul><li>祜（hù）：福；劭（shào）：美好</li></ul></li><li><strong>矩步引领，俯仰廊庙。</strong> 步履规矩，昂首挺胸；俯仰之间，皆合廊庙之礼。</li><li><strong>束带矜庄，徘徊瞻眺。</strong> 束好衣带，庄重矜持；徘徊其间，四处瞻望。</li><li><strong>孤陋寡闻，愚蒙等诮。</strong> 孤陋寡闻之人，与愚蒙之辈同受讥诮。 <ul><li>自谦之语，也是警示</li></ul></li><li><strong>谓语助者，焉哉乎也。</strong> 所谓语气助词，就是焉、哉、乎、也。 <ul><li>全文以虚词作结，点明文字教学之用途</li></ul></li></ul>",3)),t(e,{items:[{term:"蓝笋象床",pinyin:["lán","sǔn","xiàng","chuáng"],meaning:"蓝笋是竹席，象床是象牙装饰之床。昼眠夕寐、蓝笋象床，写居处安适——这是全书由大及小收拢的第一步。"},{term:"弦歌酒宴",pinyin:["xián","gē","jiǔ","yàn"],meaning:"弦歌设宴、接杯举觞；矫手顿足，悦豫且康——写宴饮之乐，手足起舞而身心安和。"},{term:"稽颡再拜",pinyin:["qǐ","sǎng","zài","bài"],meaning:"叩头再拜、心怀敬畏。这一句与前面的「弦歌酒宴」相接，是古人生活里乐与敬的两面。"},{term:"骸垢想浴",pinyin:["hái","gòu","xiǎng","yù"],meaning:"身上有垢便想沐浴，手里执热便愿清凉——写人情之常。古人以这类「人之常情」收束日用之事。"},{term:"布射僚丸",pinyin:["bù","shè","liáo","wán"],meaning:"吕布射戟以解刘备之围，宜僚弄丸而使楚宋之兵不战——一武一技，都能排解纷争。"},{term:"嵇琴阮啸",pinyin:["jī","qín","ruǎn","xiào"],meaning:"嵇康善琴、阮籍长啸，是魏晋名士的两种自处方式。"},{term:"恬笔伦纸",pinyin:["tián","bǐ","lún","zhǐ"],meaning:"相传蒙恬改良毛笔、蔡伦改进造纸。钧巧任钓：马钧之巧、任公子之钓。四句连写技艺与器物。"},{term:"毛施淑姿",pinyin:["máo","shī","shū","zī"],meaning:"毛嫱（一说毛嫱为越地美姬）与西施，姿容美好；工颦妍笑，指善颦与美笑皆成妍态。"},{term:"谓语助者",pinyin:["wèi","yǔ","zhù","zhě"],meaning:"末句以「焉、哉、乎、也」四个语助词收尾。全文一千字不重不漏，最后落在四个虚字上，反倒最见巧思。"}]}),n[17]||(n[17]=r('<h2 id="notes" tabindex="-1">现代解读与启发 <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;现代解读与启发 {#notes}&quot;">​</a></h2><p>读《千字文》和读《庄子》《系辞》的感觉不太一样。它不是要辩什么、破什么，而是把一千个字摆得整整齐齐——从天上讲到地上，从上古讲到眼前的日子，像在一天之内把中国文化的骨架走了一遍。</p><p><strong>先说它的走法。</strong> 前两句还在「天地玄黄，宇宙洪荒」，九句之后就落到了「海咸河淡，鳞潜羽翔」。由大到小、由远及近，一层层收下来。我读的时候特意留意了这个次序：先立天地，再讲人事，最后落到穿衣吃饭、祭祀起居——几乎没有一句是悬空的。这种「从最大处起笔，从最小处落脚」的写法，本身就是一种态度。</p><p><strong>再说它的收尾。</strong> 一千字不重不漏，最后却落在「谓语助者，焉哉乎也」——四个虚字上。刚开始读觉得奇怪，后来反而觉得这是全篇最巧的地方：前面九百多个字都在讲实的东西（天、地、人、事、物），最后用四个没有实义的虚字收住。像是在说：讲了这么多，真正起作用的，往往是那些不显眼的东西。</p><p><strong>有几个句子，我停得比较久。</strong></p><ul><li><strong>「知过必改，得能莫忘」</strong>——八个字把进学的两件事说尽了：一是改过，二是记得住学过的好东西。加上前面读《系辞》时印象很深的「无咎者，善补过者也」，我对「改过」的理解又深了一层：不是要求自己不犯错，而是犯了错能改。</li><li><strong>「尺璧非宝，寸阴是竞」</strong>——一尺的璧玉不算宝，一寸的光阴才值得争。这句和《庄子》里「吾生也有涯」是两种口吻：庄子说的是有限，这里说的是珍惜。</li><li><strong>「性静情逸，心动神疲」「守真志满，逐物意移」</strong>——这两句是我这次读得最慢的。心一动，神就疲；守住本真，志向才充实；一味追着外物跑，心就散了。这和我读《系辞》时分辨的「觉知」是一路的——知道自己在做什么，心才安得住。</li><li><strong>「孤陋寡闻，愚蒙等诮」</strong>——快要收尾时，它忽然自谦了一句。一篇讲了一千字天地人事的文章，最后说自己「孤陋寡闻」，这份自知反倒让人敬重。</li></ul><p><strong>最后一点感受。</strong>《千字文》是童蒙识字课本，一千字，一天就能通读一遍。但它讲的次序——由天及地、由外及内、由史及身、由起居收束——以及「不重不漏」的那种节制，是可以一直用的：写字如此，读书如此，做事大概也如此。</p><p>读到这里，我觉得它不只是一本认字的书。它更像是把「中国文化的基本盘」压缩成一千个字，交给一个刚开始认字的人——而这个人，今天也可以是我。</p><h2 id="附录一-重要典故速查" tabindex="-1">附录一：重要典故速查 <a class="header-anchor" href="#附录一-重要典故速查" aria-label="Permalink to &quot;附录一：重要典故速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>典故</th><th>出处 / 人物</th></tr></thead><tbody><tr><td>墨子悲丝染</td><td>《墨子·所染》近朱者赤</td></tr><tr><td>甘棠遗爱</td><td>《诗经·甘棠》召伯听讼</td></tr><tr><td>两疏见机</td><td>汉·疏广疏受叔侄功成身退</td></tr><tr><td>王充耽读</td><td>《后汉书》王充书肆读书</td></tr><tr><td>磻溪垂钓</td><td>姜太公遇文王</td></tr><tr><td>伊尹阿衡</td><td>商汤之贤相</td></tr><tr><td>周公营洛</td><td>周公旦营建洛邑</td></tr><tr><td>桓公匡合</td><td>齐桓公九合诸侯</td></tr><tr><td>起翦颇牧</td><td>白起王翦廉颇李牧·战国四将</td></tr><tr><td>假途灭虢</td><td>晋献公·春秋典故</td></tr><tr><td>布射僚丸</td><td>吕布·宜僚·技艺典故</td></tr><tr><td>嵇琴阮啸</td><td>嵇康·阮籍·竹林七贤</td></tr><tr><td>恬笔伦纸</td><td>蒙恬造笔·蔡伦造纸</td></tr></tbody></table><h2 id="附录二-难读字注音" tabindex="-1">附录二：难读字注音 <a class="header-anchor" href="#附录二-难读字注音" aria-label="Permalink to &quot;附录二：难读字注音&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字</th><th>音</th><th>字</th><th>音</th><th>字</th><th>音</th></tr></thead><tbody><tr><td>昃</td><td>zè</td><td>辰宿</td><td>xiù</td><td>柰</td><td>nài</td></tr><tr><td>律吕</td><td>lǚ</td><td>稼穑</td><td>jià sè</td><td>俶</td><td>chù</td></tr><tr><td>黜陟</td><td>chù zhì</td><td>猷</td><td>yóu</td><td>輶</td><td>yóu</td></tr><tr><td>稽颡</td><td>qǐ sǎng</td><td>烝尝</td><td>zhēng</td><td>縻</td><td>mí</td></tr><tr><td>鹍</td><td>kūn</td><td>绛</td><td>jiàng</td><td>骧</td><td>xiāng</td></tr><tr><td>祜</td><td>hù</td><td>劭</td><td>shào</td><td>弁</td><td>biàn</td></tr><tr><td>皋</td><td>gāo</td><td>寔</td><td>shí</td><td>邈</td><td>miǎo</td></tr></tbody></table><h2 id="附录三-背景简介" tabindex="-1">附录三：背景简介 <a class="header-anchor" href="#附录三-背景简介" aria-label="Permalink to &quot;附录三：背景简介&quot;">​</a></h2><ul><li><strong>作者</strong>：周兴嗣（约 470—521 年），南朝梁代文学家。</li><li><strong>成书</strong>：梁武帝萧衍命人从王羲之书法中选出一千个不重复的字，令周兴嗣一夜之间编成有意义的文章；周兴嗣呕心沥血，天明时须发皆白。</li><li><strong>地位</strong>：与《三字经》《百家姓》并称「三百千」，是中国古代最重要的三部蒙学读物之一。</li><li><strong>特点</strong>：全文 250 句，每句四字，共一千字，无一重复；内容涵盖天文、地理、历史、伦理、农业、人物等。</li></ul>',14))])}const q=a(u,[["render",p]]);export{x as __pageData,q as default};
